export const ICON_NAMES = Object.keys(PHOSPHOR_ICONS);

export function getIconBody(name: string | null | undefined): string {
  if (name && PHOSPHOR_ICONS[name]) return PHOSPHOR_ICONS[name];
  return PHOSPHOR_ICONS[FALLBACK_ICON];
}

export function isKnownIcon(name: unknown): name is string {
  return typeof name === 'string' && name in PHOSPHOR_ICONS;
}
